import csv,statistics as s
from datetime import date
D={}
for r in csv.DictReader(open('data/daily.csv')):
 D.setdefault(r['date'],{})[r['region']]=float(r['completion_time_seconds'])
r=[((date.fromisoformat(d)-date(2026,3,15)).days,v['East'],v['West']) for d,v in sorted(D.items())]
for label,rows in [('pre',r[:42]),('post',r[42:]),('Q2',[x for x in r if x[0]>=17])]:
 print(label,len(rows),[(s.mean(v),s.median(v)) for v in zip(*rows)])
for n in (42,28,21,14):
 p=r[42-n:42]; m,b=s.linear_regression([x for x,e,w in p],[w-e for x,e,w in p]); print(n,m,b,[s.mean(w-e-(b+m*x) for x,e,w in q) for q in (r[42:],r[42:49],r[59:])])
for i in range(0,len(r),7):
 print(r[i][0],*[round(s.mean(z),2) for z in zip(*[(e,w,w-e) for x,e,w in r[i:i+7]])])
PY"

